const sample = {
  "demo": true,
  "from": "legal@harbor.example",
  "filename": "harbor-msa.pdf",
  "vendor": "Harbor & Co",
  "invoiceNumber": "MSA-12",
  "subtotal": 24000,
  "tax": 0,
  "total": 24000,
  "dueDate": "2027-01-01",
  "text": "Vendor: Harbor & Co\nInvoice MSA-12\nSubtotal 24000.00\nTax 0.00\nTotal 24000.00\nDue 2027-01-01\n"
};
const incoming = $input.first()?.json ?? {};
const provided = Object.keys(incoming).filter((key) => incoming[key] !== undefined && incoming[key] !== null && incoming[key] !== '');
const base = provided.length ? { ...sample, ...incoming } : { ...sample };
const flag = incoming.demo;
base.demo = !(flag === false || flag === 'false' || flag === 0 || flag === '0');
return [{ json: base }];

const item = $input.first().json;
const produced = (() => {

const text = String(item.text || item.body || '');
const vendor = item.vendor || (text.match(/vendor[:\s]+([^\n]+)/i) || [])[1] || 'Unknown vendor';
const invoiceNumber = item.invoiceNumber || (text.match(/inv(?:oice)?\s*#?\s*([A-Z0-9-]+)/i) || [])[1] || 'UNKNOWN';
const currency = item.currency || 'USD';
const total = Number(item.total ?? matchAmount(text, 'total') ?? 0);
const tax = Number(item.tax ?? matchAmount(text, 'tax') ?? 0);
const subtotal = Number(item.subtotal ?? matchAmount(text, 'subtotal') ?? (total - tax));
const dueDate = item.dueDate || (text.match(/due[:\s]+(\d{4}-\d{2}-\d{2})/i) || [])[1] || '';
const expected = Math.round((subtotal + tax) * 100) / 100;
const balanced = Math.abs(expected - total) <= Math.max(0.5, total * 0.02);
const record = {
  vendor: String(vendor).trim(),
  invoiceNumber,
  currency,
  subtotal,
  tax,
  total,
  dueDate,
  balanced,
  mailbox: item.from || '',
  filename: item.filename || 'invoice.pdf',
  destination: 'Contract register',
};
return {
  summary: record.vendor + ' ' + invoiceNumber + ' for ' + total + ' ' + currency + (balanced ? ' balances.' : ' does not balance.'),
  route: balanced ? 'post' : 'review',
  record,
  slackText: (balanced ? 'Post' : 'Review') + ' invoice ' + invoiceNumber + ' from ' + record.vendor + ' (' + total + ' ' + currency + ').',
  actions: [{ app: 'Contract register', operation: balanced ? 'create' : 'flag', payload: record }],
};
function matchAmount(source, label) {
  const pattern = new RegExp(label + '[:\\s]*\\$?([0-9,]+(?:\\.[0-9]{2})?)', 'i');
  const found = source.match(pattern);
  return found ? Number(found[1].replace(/,/g, '')) : null;
}

})();
if (!produced || typeof produced.summary !== 'string' || !produced.summary.trim()) {
  throw new Error('Apply rules must return a summary string');
}
return [{
  json: {
    ...item,
    ...produced,
    demo: item.demo !== false,
  },
}];

const item = $input.first().json;
return [{
  json: {
    demo: true,
    status: 'demo_ready',
    workflow: 'contract-key-terms',
    summary: item.summary,
    route: item.route ?? null,
    record: item.record ?? {},
    actions: item.actions ?? [],
    slackText: item.slackText ?? item.summary,
    notes: 'Demo mode did not call external apps. Send {"demo": false} after placeholder credentials are replaced.',
  },
}];
